    /// <summary>
    /// Creates a <c>METSalesInvoicePostedBusinessEventContract</c> from a <c>CustInvoiceJour</c> record.
    /// </summary>
    /// <param name = "_custInvoiceJour">A <c>CustInvoiceJour</c> record.</param>
    /// <returns>A <c>METSalesInvoicePostedBusinessEventContract</c>.</returns>
    public static METSalesInvoicePostedBusinessEventContract newFromCustInvoiceJour(CustInvoiceJour _custInvoiceJour)
    {
        var contract = new METSalesInvoicePostedBusinessEventContract();
        contract.initialize(_custInvoiceJour);

        return contract;
    }

    [DataMember('LegalEntity'), BusinessEventsDataMember("@AccountsReceivable:LegalEntity")]
    public LegalEntityDataAreaId parmLegalEntity(LegalEntityDataAreaId _legalEntity = legalEntity)
    {
        legalEntity = _legalEntity;

        return legalEntity;
    }
